/* ===== REBRAND · productos, nivel 2, logo ===== */
const LOGO="data:image/webp;base64,";
const CATS=[['slots','Slots','Tragamonedas inspiradas en la cultura peruana'],['live','Casino en vivo','Ruleta, cartas y baccarat'],['arcade','Arcade','Partidas rápidas para cualquier momento']];
const GCAT={slots:'slots',roulette:'live',blackjack:'live',poker:'live',baccarat:'live',mines:'arcade',wheel:'arcade',dice:'arcade'};
function locked(id){const u=current();return id!=='slots'&&!!u&&(u.level||1)<2}
function showLvl(id){const g=games.find(x=>x.id===id);$('lvlText').textContent='Para jugar '+g.name+' debes alcanzar el nivel 2. Mientras tanto, disfruta de Sol Dorado.';$('lvlModal').classList.remove('hidden')}
function closeLvl(){$('lvlModal').classList.add('hidden')}
function lvlPlay(){closeLvl();openGame('slots')}
function deleteUser(id){
  const us=getUsers(),u=us.find(x=>x.id===id);if(!u)return;
  if(!confirm('¿Eliminar la cuenta de '+u.name+' ('+u.identifier+')?\n\nSe borrarán sus datos, saldo, cartas y transacciones. Esta acción no se puede deshacer.'))return;
  saveUsers(us.filter(x=>x.id!==id));
  try{const m=mailStore();delete m[id];mailSave(m)}catch(e){}
  try{txSave(txAll().filter(t=>t.uid!==id))}catch(e){}
  try{localStorage.removeItem('sdfs_'+id);localStorage.removeItem('sdq_sdfs_'+id)}catch(e){}
  renderAdmin();try{renderAdminTx()}catch(e){}
  toast('Cuenta eliminada.');
}
function setLevel(id,v){const us=getUsers(),u=us.find(x=>x.id===id);if(!u)return;u.level=Number(v);saveUsers(us);toast('Nivel actualizado.')}
gameCard=function(g){const lk=locked(g.id),art=g.id==='slots';
  return `<article class="game${art?' feat art':''}${lk?' locked':''}"><div class="game-bg" style="background-image:url('${art?SD_ART.bg:g.bg}')"></div><div class="game-content"><div><div class="game-top">${icon(g.icon)}<span class="game-tag">${lk?'Nivel 2':g.tag}</span></div><h3>${g.name}</h3><p>${g.desc}</p></div><div class="game-actions">${lk?`<button class="btn small lockbtn" onclick="openGame('${g.id}')">${ICONS.lock}Nivel 2</button>`:`<button class="btn gold small" onclick="openGame('${g.id}')">${ic('play')}<span>Jugar</span></button>`}</div></div></article>`};
function sect(p,c,ban){const l=games.filter(g=>GCAT[g.id]===c[0]);
  return `<div class="sec-head" id="${p}-${c[0]}"><span class="sh-ico">${ICONS[{slots:'slots',live:'roulette',arcade:'dice'}[c[0]]]||''}</span><div class="sh-txt"><h2>${c[1]}</h2><p>${c[2]}</p></div></div>${ban?`<a class="tile pban" onclick="${ban}"><img data-ph="${c[0]}" alt="${c[1]}"></a>`:''}<div class="games-grid${l.length===3?' g3':''}">${l.map(gameCard).join('')}</div>`}
function renderHome(){$('homeProducts').innerHTML=sect('h',CATS[0],'playSol()')+sect('h',CATS[1],'goGames()')+sect('h',CATS[2])}
renderCasino=function(){const u=current();if(!u)return;syncHeader();$('casinoName').textContent=u.name.split(' ')[0];const l=u.level||1;
  $('lvlNote').innerHTML=l<2?'<b>Nivel '+l+'</b><span>Sol Dorado está disponible. Alcanza el nivel 2 para jugar el resto de los juegos.</span>':'<b>Nivel '+l+'</b><span>Todos los juegos están desbloqueados.</span>';
  $('casinoGames').innerHTML=CATS.map(c=>sect('c',c)).join('');$('gameArea').classList.add('hidden');$('gameArea').innerHTML=''};
function goProduct(k){const go=()=>{const e=$((document.body.dataset.view==='casino'&&k!=='extra'&&k!=='pagos'?'c-':'h-')+k);if(e)e.scrollIntoView({behavior:'smooth',block:'start'})};
  if(document.body.dataset.view==='casino'&&(k==='extra'||k==='pagos')){showOnly('home');setTimeout(go,120)}else go()}
const _so=showOnly;showOnly=function(id){document.body.dataset.view=id;setTimeout(()=>window.dispatchEvent(new Event('scroll')),80);return _so(id)};
document.body.dataset.view=['home','auth','casino','profile','admin'].find(x=>!$(x).classList.contains('hidden'))||'home';
document.querySelectorAll('[data-logo]').forEach(e=>e.src=LOGO);
const LOGO_LT="data:image/webp;base64,";{const e=document.getElementById('ltLogo');if(e)e.src=LOGO_LT}
document.querySelectorAll('#lvlModal .lk').forEach(e=>e.innerHTML=ICONS.lock);
renderHome();
if(current()&&!$('casino').classList.contains('hidden'))renderCasino();
